import{_ as e,o as t,c as l,a2 as i}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"MultiPlanet","description":"","frontmatter":{"title":"MultiPlanet","order":11},"headers":[],"relativePath":"zh/mods/multiplanet.md","filePath":"zh/mods/multiplanet.md","lastUpdated":1786943111000}'),o={name:"zh/mods/multiplanet.md"};function n(r,a,s,d,u,c){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="multiplanet" tabindex="-1">MultiPlanet <a class="header-anchor" href="#multiplanet" aria-label="Permalink to &quot;MultiPlanet&quot;">​</a></h1><blockquote><p>解锁《冰与火之舞》MultiPlanet 事件的行星数量限制，支持 <strong>2–8 个行星</strong>（官方原版限制 2–3）。</p><p>项目地址：<a href="https://github.com/adofaiex/MultiPlanet" target="_blank" rel="noreferrer">https://github.com/adofaiex/MultiPlanet</a></p></blockquote><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>✅ 解锁 MultiPlanet 事件的 <code>planets</code> 属性，支持 2–8 个行星</li><li>✅ 编辑器中使用滑动条调整行星数量（范围 2–8）</li><li>✅ 新建 MultiPlanet 事件时 <code>planets</code> 自动重置为 2（避免继承上一个事件的值）</li><li>✅ 移除编辑器中对 &gt;3 行星的警告</li><li>✅ 移除游戏运行时的硬编码限制</li><li>🆕 <strong>关卡转换器</strong>：将任意关卡转换为多行星版本（2–8 个行星）</li></ul><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ol><li><p>确保已安装 <a href="https://www.nexusmods.com/site/mods/21" target="_blank" rel="noreferrer">Unity Mod Manager</a> 并启用了 ADOFAI 的模组支持</p></li><li><p>将 <code>MultiPlanet.dll</code> 和 <code>Info.json</code> 复制到：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>\\A Dance of Fire and Ice\\Mods\\MultiPlanet\\</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>启动游戏，在 Mod 列表中启用 MultiPlanet</p></li></ol><h2 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to &quot;使用方法&quot;">​</a></h2><h3 id="使用-multiplanet-事件" tabindex="-1">使用 MultiPlanet 事件 <a class="header-anchor" href="#使用-multiplanet-事件" aria-label="Permalink to &quot;使用 MultiPlanet 事件&quot;">​</a></h3><ol><li>打开关卡编辑器</li><li>添加 <strong>MultiPlanet</strong> 事件到任意轨道</li><li>在属性面板中，<code>planets</code> 现在显示为<strong>滑动条</strong>（或数字输入框），可调 2–8</li></ol><h3 id="关卡转换器" tabindex="-1">关卡转换器 <a class="header-anchor" href="#关卡转换器" aria-label="Permalink to &quot;关卡转换器&quot;">​</a></h3><p>将任意关卡转换为多行星版本（2–8 个行星）。</p><blockquote><p>📝 转换器的详细操作步骤待补充。</p></blockquote><h2 id="疑难解答" tabindex="-1">疑难解答 <a class="header-anchor" href="#疑难解答" aria-label="Permalink to &quot;疑难解答&quot;">​</a></h2><blockquote><p>📝 待补充（欢迎在仓库 Issues 中反馈）</p></blockquote>',14)])])}const m=e(o,[["render",n]]);export{h as __pageData,m as default};
